import{z as o,x as i,o as r,c as p,q as s,j as B,D as e,d as A,s as n,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"PAUSE 与 PFC","description":"","frontmatter":{"title":"PAUSE 与 PFC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pause-pfc.md","filePath":"cs/pause-pfc.md","lastUpdated":1791413859000}'),P={name:"cs/pause-pfc.md"};function C(d,E,F,c,u,D){const t=i("Mermaid");return r(),p("div",null,[E[2]||(E[2]=s('<h1 id="pause-与-pfc" tabindex="-1">PAUSE 与 PFC <a class="header-anchor" href="#pause-与-pfc" aria-label="Permalink to &quot;PAUSE 与 PFC&quot;">​</a></h1><div class="epigraph"><p>链路层暂停是跳上的反压，不是端到端窗口；PFC 按优先级暂停，避免一张暂停卡死全部类别。</p><footer>—— 据 IEEE 802.3x PAUSE；IEEE 802.1Qbb PFC 整理</footer></div><p><a href="/cs/autonegotiation">上一课</a>可广告流控能力。缺口是<strong>暂停帧做什么</strong>：<a href="/cs/tcp-window">TCP 窗口</a> 保护接收主机；交换机输出队列满时，需要一跳内让对端停发。<a href="/cs/layering-e2e">端到端论证</a> 提醒：这是性能优化，不是文件正确性。本课不把巨帧 MTU 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>802.3x PAUSE：对端停止该口全部发送一段时间。无损存储网（后课 RoCE）怕丢包，于是用 PFC：八个优先级各有暂停，背压只打中无丢类别。HOL 后课会说明为何整口暂停会让无关流饿死——PFC 是针对类别的补丁，不是交换机结构的最终解。</p><p><span class="marginnote">「反压」（backpressure）翻译成白话：下游堵了，直接通知上游「先别发」。直觉类比：水管末端捏住，压力沿管子往回传。它和 TCP 的 rwnd 不一样——rwnd 是两端主机之间按字节记账的窗口，PAUSE/PFC 只是相邻两台设备之间、以微秒计的「临时闭嘴」。</span></p><p>PAUSE 跨越中间交换机时会传播拥塞，形成「停车波」。这不是 AIMD，没有公平定理。</p><p><span class="marginnote">「停车波」直觉：高速公路上一辆车轻点刹车，后车依次更重地刹车，波会往回传好几公里——哪怕最初的路况并不真堵。暂停帧沿交换机逐跳回传时同理，一个出口的拥塞能让几跳之外的无关端口也停一阵。</span></p><p><span class="marginnote">PFC 依赖 802.1p 优先级字段。配错类别会让控制面 BPDU 也被暂停。本课不把 DCQCN 算法写完。</span></p><h3 id="暂停不是-rwnd" tabindex="-1">暂停不是 rwnd <a class="header-anchor" href="#暂停不是-rwnd" aria-label="Permalink to &quot;暂停不是 rwnd&quot;">​</a></h3><p>一跳反压保护邻机队列，不保护文件正确性。整口 PAUSE 会冻无关流；PFC 按类补，仍可能传播停车波。公网核心不要开。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>接收方队列过阈 → 发 PAUSE/PFC → 发送方停止对应队列 → 阈下恢复。画与 TCP 对照：rwnd 在两端主机；PAUSE 在相邻 MAC。不要用 PAUSE 替代拥塞控制来跑广域 TCP。</p>',13)),(r(),B(l,null,{default:e(()=>[n(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%87%BA%E5%8F%A3%E9%98%9F%E5%88%97%E8%BF%87%E9%98%88%22%5D%20--%3E%20PF%5B%22PAUSE%20%E6%88%96%20PFC%22%5D%0A%20%20PF%20--%3E%20NB%5B%22%E9%82%BB%E6%9C%BA%E5%81%9C%E5%8F%91%22%5D%0A%20%20NB%20--%3E%20DRAIN%5B%22%E9%98%9F%E5%88%97%E6%8E%92%E6%B3%84%22%5D%0A%20%20DRAIN%20--%3E%20RSM%5B%22%E6%81%A2%E5%A4%8D%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"主干交换课把全双工链路当成总能塞帧。本课承认缓冲有限。生成树阻塞口不发数据，与暂停不同：阻塞是拓扑，暂停是瞬态反压。LACP 后课的成员口各自暂停，逻辑链路仍在。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"常见误区：把 PFC 当拥塞控制。它没有加性增、乘性减，也没有公平性定理，只是邻居之间的紧急刹车；真正把发送速率调回来的是 DCQCN 这类端到端算法。PFC 配错阈值时丢包照样发生，「无损以太网」是有前提的合同，不是物理定律。")],-1)),(r(),B(l,null,{default:e(()=>[n(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%90%8C%E4%B8%80%E7%AB%AF%E5%8F%A3%EF%BC%9A%E5%AD%98%E5%82%A8%E6%B5%81%20%2B%20%E6%99%AE%E9%80%9A%E6%B5%81%E9%87%8F%22%5D%20--%3E%20C%7B%22%E9%98%9F%E5%88%97%E8%BF%87%E9%98%88%EF%BC%8C%E6%80%8E%E4%B9%88%E5%81%9C%EF%BC%9F%22%7D%0A%20%20C%20--%20%22802.3x%20PAUSE%22%20--%3E%20P1%5B%22%E6%95%B4%E4%B8%AA%E7%AB%AF%E5%8F%A3%E5%85%A8%E9%83%A8%E5%81%9C%E5%8F%91%22%5D%0A%20%20P1%20--%3E%20P2%5B%22%E6%97%A0%E5%85%B3%E6%99%AE%E9%80%9A%E6%B5%81%E8%A2%AB%E8%BF%9E%E5%9D%90%E9%A5%BF%E6%AD%BB%22%5D%0A%20%20C%20--%20%22PFC%20%E6%8C%89%E4%BC%98%E5%85%88%E7%BA%A7%22%20--%3E%20F1%5B%22%E5%8F%AA%E6%9A%82%E5%81%9C%E6%8B%A5%E5%A1%9E%E7%9A%84%E5%AD%98%E5%82%A8%E7%B1%BB%E5%88%AB%22%5D%0A%20%20F1%20--%3E%20F2%5B%22%E5%85%B6%E4%BB%96%E7%B1%BB%E5%88%AB%E7%85%A7%E5%B8%B8%E8%BD%AC%E5%8F%91%22%5D%0A%20%20P2%20--%3E%20W%5B%22%E4%B8%94%E6%9A%82%E5%81%9C%E9%80%90%E8%B7%B3%E5%9B%9E%E4%BC%A0%EF%BC%9A%E5%81%9C%E8%BD%A6%E6%B3%A2%E6%89%A9%E6%95%A3%22%5D%0A%20%20F2%20--%3E%20W2%5B%22%E4%BB%8D%E5%8F%AF%E8%83%BD%E9%80%90%E8%B7%B3%E4%BC%A0%E6%92%AD%EF%BC%9A%E9%9C%80%E8%B0%83%E9%98%88%E5%80%BC%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=s('<p>无损以太网 = 不丢 + 必须有足够缓冲与PFC 调参；丢仍可能发生在阈值配错时。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入量化拥塞通知的全部反馈环。巨帧与 MTU 是下一课。后课默认：PAUSE 整口、PFC 按类；都是一跳反压。</p><p>不要在互联网核心开 PFC：没有统一优先级语义，暂停会放大故障。</p><p>下一课<a href="/cs/jumbo-mtu">巨帧与 MTU</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PAUSE/PFC 是链路反压，不是 rwnd。</li><li>PFC 按优先级隔离暂停，仍可能传播拥塞。</li><li>端到端正确性仍在 TCP/应用。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：IEEE 802.3x；IEEE 802.1Qbb。</li></ul>',7))])}const f=o(P,[["render",C]]);export{m as __pageData,f as default};
